### Elasticsearch Version

Sometime in v8, present in current release

### Installed Plugins

_No response_

### Java Version

_bundled_

### OS Version

_any_

### Problem Description

Elasticsearch nested query with inner hits and top-hits aggregation will return illegal_state_exception.



### Steps to Reproduce

This might even be able to reduced further, but the single doc with these fields is enough.

```
DELETE test

PUT test
{
    "mappings": {
        "properties": {
            "nested_item": {
                "type": "nested",
                "properties": {
                    "title": {
                        "type": "text"
                    },
                    "keyword3": {
                        "type": "keyword"
                    },
                    "content": {
                        "type": "text"
                    },
                    "number": {
                        "type": "long"
                    }
                }
            }
        }
    }
}

POST test/_doc
{
    "nested_item": [
        {
            "title": "foo"
        },
        {
            "keyword3": "foobar",
            "title": "foobar",
            "content": "foobar`foobar"
        },
        {
            "title": "baz| barz",
            "content": "foobar`foobar",
            "number": "2"
        }
    ]
}

POST test/_search
{
    "aggregations": {
        "nested_item": {
            "aggregations": {
                "nested_item_filter": {
                    "aggregations": {
                        "0": {
                            "aggregations": {
                                "01": {
                                    "top_hits": {}
                                }
                            },
                            "filter": {
                                "bool": {
                                    "should": []
                                }
                            }
                        }
                    },
                    "filter": {
                        "bool": {
                            "should": []
                        }
                    }
                }
            },
            "nested": {
                "path": "nested_item"
            }
        }
    },
    "query": {
        "nested": {
            "inner_hits": {},
            "path": "nested_item",
            "query": {
                "bool": {
                    "should": []
                }
            }
        }
    }
}
```

